  font-family: var(--font-pixel);
  font-size: 1.1rem;
  font-weight: bold;
  margin-bottom: 28px;
  background: #111f16;
  border: var(--border-thick) double var(--retro-accent);
  border-radius: 0;
  box-shadow: 0 2px 0 #293f22;
  min-height: 36px;
  padding: 10px 18px 8px 18px;
  letter-spacing: 2px;
  text-shadow: 2px 2px 0 #127f1a, 0 1px 0 #ffe999;
}

.retro-statusbar.draw {
  color: #ab7b14;
  border-color: #fff460;
  background: #2f220c;
}

.retro-cell-btn {
  width: 68px;
  height: 68px;
  font-family: var(--font-pixel);
  font-size: 2.3rem;
  font-weight: bold;
  background: #dbb764;
  color: #262626;
  border: var(--border-thick) solid var(--retro-border);
  border-radius: 0;
  box-shadow:
    0 1.5px 0 #fffbe7,
    0 0 0 2px #d1c07b,
    0 0 3px 3px #b99a61 inset;
  cursor: pointer;
  outline: none;
  text-shadow: 1.5px 1.5px 0 #fff2a6, 0 4px 0 #b59b5a;
  user-select: none;
  padding: 0;
  transition: background 0.14s, color 0.1s;
}

.retro-cell-btn:disabled,
.retro-cell-btn[disabled] {
  background: #f1e3c3;
  color: #adab98;
  text-shadow: none;
  box-shadow: none;
  cursor: not-allowed;
}

.retro-cell-x {
  color: #be332a;
  text-shadow: 2px 2px 0 #fff0ef, 0 3px 0 #711209;
}

.retro-cell-o {
  color: #1749be;
  text-shadow: 2px 2px 0 #e7e8f9, 0 3px 0 #283c72;
}

.retro-board:before, .retro-board:after {
  content: '';
  display: none;
}


.retro-board {
  background: var(--retro-board);
  border: var(--border-thick) solid var(--retro-border);
  border-radius: 0;
  box-shadow: var(--shadow-retro);
