  gap: 10px;
}

.retro-statusbar {
  color: var(--retro-accent);
  font-family: var(--font-pixel);
  font-size: 1.1rem;
  font-weight: bold;
  margin-bottom: 28px;
  background: #111f16;
  border: var(--border-thick) double var(--retro-accent);
  border-radius: 0;
  box-shadow: 0 2px 0 #293f22;
  min-height: 36px;
  padding: 10px 18px 8px 18px;
  letter-spacing: 2px;
  text-shadow: 2px 2px 0 #127f1a, 0 1px 0 #ffe999;
}

.retro-statusbar.draw {
  color: #ab7b14;
  border-color: #fff460;
  background: #2f220c;
}

