  border: var(--border-thick) solid var(--retro-border);
  border-radius: 0;
  box-shadow: var(--shadow-retro);
  padding: 18px 16px 22px 16px;
  display: grid;
  grid-template-columns: repeat(3, 68px);
  grid-template-rows: repeat(3, 68px);
  gap: 10px;
}

.retro-statusbar {
  color: var(--retro-accent);
  font-family: var(--font-pixel);
  font-size: 1.1rem;
  font-weight: bold;
  margin-bottom: 28px;
  background: #111f16;
  border: var(--border-thick) double var(--retro-accent);
  border-radius: 0;
  box-shadow: 0 2px 0 #293f22;
  min-height: 36px;
  padding: 10px 18px 8px 18px;
  letter-spacing: 2px;
  text-shadow: 2px 2px 0 #127f1a, 0 1px 0 #ffe999;
}

.retro-statusbar.draw {
  color: #ab7b14;
  border-color: #fff460;
  background: #2f220c;
}

.retro-cell-btn {
  width: 68px;
  height: 68px;
  font-family: var(--font-pixel);
  font-size: 2.3rem;
  font-weight: bold;
  background: #dbb764;
  color: #262626;
  border: var(--border-thick) solid var(--retro-border);
  border-radius: 0;
  box-shadow:
    0 1.5px 0 #fffbe7,
    0 0 0 2px #d1c07b,
    0 0 3px 3px #b99a61 inset;
  cursor: pointer;
  outline: none;
  text-shadow: 1.5px 1.5px 0 #fff2a6, 0 4px 0 #b59b5a;
  user-select: none;
  padding: 0;
  transition: background 0.14s, color 0.1s;
}

.retro-cell-btn:disabled,
.retro-cell-btn[disabled] {
  background: #f1e3c3;
  color: #adab98;
  text-shadow: none;
  box-shadow: none;
  cursor: not-allowed;
}

.retro-cell-x {
  color: #be332a;
